// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"en","term":"Market capitalization","aka":["market cap","mcap"],"short":"Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply.","body":[["Market cap lets you compare the size of projects fairly. A coin priced at 0.01 ",["USDT","usdt"]," can be worth far more in total than a coin priced at 500 USDT, depending on how many coins exist. Data sites rank coins by market cap, which is why you see ",["BTC","bitcoin"]," and ",["ETH","ethereum"]," at the top."],["The figure depends on the ",["circulating supply","circulating-supply"]," estimate, which data providers calculate differently. Coins held by the team, foundation or investors under lock-up are usually excluded. That is why you should also check ",["fully diluted valuation","fully-diluted-valuation"],", which counts all coins that will ever exist."],["Market cap is not the amount of money invested, and it is not the amount you could cash out. If a large share of coins were sold at once, the price would fall, so the real liquid value can be far lower. For small coins, look at daily ",["trading volume","trading-volume"]," and order book depth alongside market cap."]],"example":"Suppose Coin A trades at 2 USDT with 500 million coins in circulation, giving a market cap of 1 billion USDT. Coin B trades at 0.02 USDT with 100 billion coins in circulation, a market cap of 2 billion USDT. Coin B looks cheaper per coin, but the project is valued at twice the size of Coin A. For Coin B to reach 2 USDT, its market cap would need to hit 200 billion USDT.","mistakes":["Judging a coin as cheap or expensive by its unit price instead of its market cap.","Treating market cap as money that has flowed in, when it is just price times supply.","Ignoring that circulating supply can grow quickly when locked tokens unlock."],"faq":[{"q":"How is crypto market cap calculated?","a":"Multiply the current price by the circulating supply. A coin at 4 USDT with 250 million coins circulating has a market cap of 1 billion USDT."},{"q":"What is the difference between market cap and FDV?","a":"Market cap uses circulating supply, while fully diluted valuation uses the maximum or total supply. A big gap between them means many tokens are still to be released."},{"q":"Why do different sites show different market caps?","a":"They use different circulating supply estimates and slightly different price sources."}],"title":"What is market cap in crypto? Meaning and formula","description":"Learn how crypto market cap is calculated, why unit price is misleading and how market cap differs from FDV.","related":[["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply."],["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens."],["trading-volume","Trading volume","Trading volume is the total amount of an asset traded over a set period, usually shown as the 24-hour volume in coins or in USD value."],["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for."],["altcoin","Altcoin","An altcoin is any cryptocurrency other than Bitcoin, a broad category that includes Ether, Solana, stablecoins, exchange tokens and memecoins."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"en","term":"Market maker","aka":["MM","liquidity provider"],"short":"A market maker is a trader or firm that continuously places both buy and sell orders on a market, providing liquidity and earning from the spread between them.","body":[["A market maker quotes a bid slightly below the ",["fair price","mark-price"]," and an ask slightly above it. When other traders hit those orders, the market maker buys low and sells high in small amounts, many times a day. The profit per trade is small, so the business depends on volume, speed and careful risk control."],["Market makers keep order books deep and spreads tight, which lowers costs for everyone else. Exchanges often attract them with lower maker fees, rebates or special programs, and token projects sometimes hire market makers to support ",["liquidity","liquidity"]," after a listing."],["The main risk for a market maker is inventory: if the price moves strongly in one direction, they end up holding the losing side. In ",["DeFi","defi"],", automated market makers (AMMs) replace human quoting with a formula and a ",["liquidity pool","liquidity-pool"],". Not every market maker is benign; some arrangements between projects and market makers have been criticised, so trading activity alone does not prove healthy demand."]],"example":["Suppose ",["ETH","ethereum"]," trades around 3,000 ",["USDT","usdt"],". A market maker posts a bid at 2,999.50 and an ask at 3,000.50 for 2 ETH each. If one trader sells 2 ETH into the bid and another buys 2 ETH from the ask, the market maker earns 2 × 1.00 = 2 USDT before fees. Repeating that thousands of times a day adds up, but a sudden 5% drop while holding 50 ETH would cost about 7,500 USDT."],"mistakes":["Thinking market makers always push prices in one direction, when their core job is quoting both sides.","Assuming a tight spread on a new token means deep liquidity, when a single market maker can pull its orders at any time.","Confusing a market maker with a maker order; any trader can place maker orders."],"faq":[{"q":"How do crypto market makers make money?","a":"Mainly by capturing the bid-ask spread on many small trades, plus maker rebates or fee discounts where exchanges offer them."},{"q":"What is the difference between a market maker and an AMM?","a":"A market maker actively places and updates orders in an order book. An AMM is a smart contract that prices trades from a pool of tokens using a formula."}],"title":"What is a market maker in crypto? Meaning explained","description":"Learn what crypto market makers do, how they earn the spread, why exchanges need them and how they differ from AMMs.","related":[["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"en","term":"Risk-reward ratio","aka":["R:R","risk/reward","reward-to-risk ratio"],"short":"The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target.","body":["You measure risk as the distance from entry to stop-loss and reward as the distance from entry to take-profit. A trade risking 100 to make 300 has a risk-reward ratio of 1:3. Some platforms and traders write it the other way round as reward-to-risk, so check which convention is being used.","The ratio matters because it works together with your win rate. With a 1:3 ratio, you can be wrong on most trades and still come out ahead. With a 1:0.5 ratio, you need to win far more often than you lose just to break even, before fees.",["A good ratio on paper is only useful if the target is realistic. Setting a take-profit far beyond a strong resistance zone makes the ratio look attractive but lowers the chance of reaching it. Fees and ",["slippage","slippage"]," also reduce the real reward, especially on short-term trades with small targets."]],"example":["Suppose you buy at 1.00 ",["USDT","usdt"]," with a stop-loss at 0.95 and a target at 1.15. Risk is 0.05 and reward is 0.15, so the ratio is 1:3. Over ten such trades with equal size, if you win 3 and lose 7, you gain 3 × 0.15 = 0.45 and lose 7 × 0.05 = 0.35 per coin, netting 0.10 per coin before fees. Break-even win rate for 1:3 is 1 ÷ (1 + 3) = 25%."],"mistakes":["Moving the stop-loss further away during the trade, which quietly destroys the planned ratio.","Picking unrealistic targets just to make the ratio look good.","Ignoring win rate and assuming a high ratio alone makes a strategy profitable."],"faq":[{"q":"What is a good risk-reward ratio?","a":"Many traders look for at least 1:2, but the right ratio depends on your win rate. A strategy that wins often can work with a lower ratio."},{"q":"How do I calculate the break-even win rate?","a":"Divide risk by the sum of risk and reward. For a 1:2 ratio that is 1 ÷ 3, about 33% before fees."}],"title":"What is the risk-reward ratio in trading? Explained","description":"Learn how to calculate the risk-reward ratio, how it links to your win rate and why realistic targets matter in crypto.","related":[["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["take-profit","Take-profit order","A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market."],["oco-order","OCO order (one-cancels-the-other)","An OCO (one-cancels-the-other) order pairs two orders, typically a take-profit and a stop-loss, so that when one of them executes, the other is automatically cancelled."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide how much you could lose before you decide how much to buy"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"en","term":"Futures contract","aka":["futures","crypto futures"],"short":"A futures contract is an agreement to buy or sell an asset at a set price in the future, which lets you trade price moves with margin and leverage without holding the asset itself.","body":[["With crypto futures you do not buy the coin. You open a position that gains when the price moves in your favour and loses when it moves against you. You can go long if you expect a rise or short if you expect a fall, which is the main difference from buying on the ",["spot market","spot-trading"],"."],["Futures are traded on margin. You post a fraction of the position value as collateral, and the exchange lets you control a larger position. That is ",["leverage","leverage"],": it multiplies both gains and losses, and if your losses eat too far into your margin, the position is liquidated."],["Crypto exchanges offer two main kinds. ",["Delivery futures","delivery-futures"]," have an expiry date and settle on that date. ",["Perpetual futures","perpetual-futures"]," never expire and use a ",["funding rate","funding-rate"]," to stay close to the spot price. Contracts can also be margined in ",["stablecoins","stablecoin"]," such as USDT or in the coin itself. Contract size, tick size, fees and margin rules differ by exchange, so read the contract specification before trading."]],"example":"Suppose BTC trades at 50,000 USDT and you open a long futures position of 0.2 BTC, worth 10,000 USDT, using 5x leverage. You post 2,000 USDT of margin. If BTC rises to 52,500 (+5%), your profit is 0.2 × 2,500 = 500 USDT, a 25% return on margin. If BTC falls 5% to 47,500, you lose 500 USDT, also 25% of your margin, before fees.","mistakes":["Thinking futures losses are limited to the price change on the margin, when they are based on the full position size.","Opening futures without knowing whether the contract is perpetual or has an expiry date.","Using maximum leverage because the exchange allows it."],"faq":[{"q":"What is the difference between futures and spot trading?","a":"In spot trading you buy and own the coin. With futures you trade a contract on its price, can go long or short, and usually use margin and leverage."},{"q":"Can you lose more than you invest in crypto futures?","a":"On most retail crypto exchanges, liquidation closes your position before your balance goes negative, and an insurance fund covers gaps. Your margin can still be lost entirely, and with cross margin more of your account is at risk."}],"title":"What is a futures contract in crypto? Explained","description":"Learn how crypto futures contracts work, how margin and leverage change your profit and loss, and perpetual versus delivery futures.","related":[["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["delivery-futures","Delivery (quarterly) futures","Delivery futures are crypto futures contracts with a fixed expiry date, such as a weekly or quarterly contract, that settle at a set price when they expire."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell."],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"en","term":"Cross margin","aka":["cross mode","cross margin mode"],"short":"Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation.","body":[["In cross mode the exchange does not ring-fence collateral per trade. Your whole available balance in that account, plus unrealized profit from winning positions, supports every open position. This gives a losing trade more room, so its ",["liquidation price","liquidation-price"]," sits further away than in ",["isolated mode","isolated-margin"]," with the same funds."],["The downside is shared risk. If one position keeps losing, it draws on the entire balance. When the account can no longer meet the total ",["maintenance margin","maintenance-margin"],", positions are liquidated and you can lose far more than the margin you had in mind for that single trade."],"Cross margin suits traders who hold related or hedged positions, or who actively manage their total exposure. Many exchanges now offer unified or multi-asset accounts where cross margin can also count other coins as collateral, with haircuts on their value. Rules for which assets count and how they are valued differ by exchange."],"example":["Suppose your account holds 3,000 ",["USDT","usdt"]," and you open a 10x long worth 5,000 USDT in cross mode, using 500 USDT as ",["initial margin","initial-margin"],". In isolated mode, a drop of about 10% would liquidate it. In cross mode, the full 3,000 USDT backs it, so the price would need to fall roughly 59% before the 3,000 USDT is used up, ignoring fees and maintenance margin. If that happened, you would lose almost all 3,000 USDT, not just 500."],"mistakes":["Thinking you only risk the initial margin of a trade when the account is in cross mode.","Keeping a large idle balance in a cross margin account that should have stayed in spot or savings.","Forgetting that a new position in cross mode changes the liquidation price of the others."],"faq":[{"q":"Is cross margin riskier than isolated margin?","a":"It delays liquidation but puts your whole balance on the line. Isolated caps the loss per position; cross can lose everything in the account."},{"q":"When does cross margin make sense?","a":"It is useful when you run hedged or offsetting positions and monitor total exposure. For single directional bets, many traders prefer isolated margin."}],"title":"What is cross margin in crypto futures? Explained","description":"Learn how cross margin shares your balance across positions, why it delays liquidation and why it can put your whole account at risk.","related":[["isolated-margin","Isolated margin","Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position."],["portfolio-margin","Portfolio margin","Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately."],["unified-trading-account","Unified trading account (UTA)","A unified trading account (UTA) is an exchange account mode that lets you trade spot, margin, futures and sometimes options from one balance, with assets shared as collateral."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Cross margin: why one loss can hit your other positions"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"en","term":"Long and short positions","aka":["going long","going short","long","short"],"short":"A long position profits when an asset's price rises, and a short position profits when its price falls.","body":[["Going long is the familiar idea of buying low and selling high. You can go long by buying a coin on the ",["spot market","spot-trading"]," or by opening a long futures position. Going short means you profit from a decline. In crypto this is usually done with ",["perpetual futures","perpetual-futures"],", by ",["spot margin","margin-trading"]," borrowing, or with options."],"The risk profiles differ. In spot, a long's maximum loss is what you paid, because price cannot fall below zero. A short has no natural ceiling on losses, because price can keep rising. With leveraged futures, both sides can be liquidated if price moves against them far enough.",["Longs and shorts are always matched in futures: for every long ",["contract","smart-contract"]," there is a short. That is why funding rates exist on perpetuals, and why the ",["long/short ratio","long-short-ratio"]," on an exchange only compares how many accounts lean one way, not the total size."]],"example":["Suppose two traders each open a 1,000 ",["USDT","usdt"]," position on a token priced at 2.00 USDT, so 500 tokens each. One goes long and one goes short. If the price rises to 2.30, the long gains 500 × 0.30 = 150 USDT and the short loses 150 USDT. If it falls to 1.60, the long loses 200 USDT and the short gains 200 USDT, before fees and funding."],"mistakes":["Assuming shorting is just the reverse of buying with the same risk; a short's loss can keep growing as price rises.","Opening a short on a thin, heavily shorted coin without considering a short squeeze.","Forgetting that funding can make holding one side expensive over time."],"faq":[{"q":"What does it mean to go long in crypto?","a":"It means taking a position that profits if the price rises, either by buying the coin or by opening a long futures contract."},{"q":"How do you short crypto?","a":"Most commonly with perpetual futures, by opening a short position. You can also borrow and sell coins with spot margin, or buy put options."}],"title":"Long vs short positions in crypto: meaning explained","description":"Learn what long and short positions mean in crypto trading, how each one profits, and the very different risks they carry.","related":[["short-selling","Short selling","Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["long-short-ratio","Long/short ratio","The long/short ratio compares how many traders or how much position size on an exchange is long versus short on a futures market, as a gauge of sentiment."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"en","term":"Short selling","aka":["shorting","going short","short"],"short":"Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price.","body":[["Classic short selling works like this: you borrow a coin, sell it immediately, and later buy the same amount back to repay the loan. If the price fell in between, you keep the difference. On crypto exchanges you can do this with ",["spot margin","margin-trading"],", paying interest on the borrowed coin."],["Most crypto traders short with ",["perpetual futures","perpetual-futures"]," instead. You simply open a short position; there is no explicit loan, but funding payments apply. Options, such as buying a put, are another way to bet on a decline with a limited maximum loss."],["Shorting carries specific risks. A price can rise much further than it can fall, so losses on an uncovered short are open-ended until you close it or get liquidated. Crowded shorts can be caught in a ",["short squeeze","short-squeeze"],", and in some markets borrowing costs or funding can rise sharply. Regulations on short selling vary by country and product."]],"example":["Suppose you borrow 10 LINK on spot margin and sell them at 15 ",["USDT","usdt"],", receiving 150 USDT. A week later LINK trades at 12 USDT. You buy 10 LINK back for 120 USDT and repay the loan, keeping 30 USDT minus interest and fees. If LINK had risen to 20 USDT instead, buying back would cost 200 USDT, a 50 USDT loss, and the loss would grow with every further rise."],"mistakes":["Underestimating that losses on a short are not capped by the amount you started with.","Ignoring borrowing interest or funding that builds up while the short stays open.","Shorting a coin only because it has gone up a lot, without a clear exit plan."],"faq":[{"q":"Can you short sell crypto on spot exchanges?","a":"Only if the exchange offers margin borrowing. Otherwise, shorting is done through futures or options."},{"q":"What is the maximum loss when shorting?","a":"In theory it is unlimited, because price can keep rising. In practice, leveraged shorts are liquidated, which limits the loss to the margin at risk."}],"title":"What is short selling in crypto? How shorting works","description":"Learn how short selling works in crypto with margin or futures, how you profit from a fall and why losses can be open-ended.","related":[["long-and-short","Long and short positions","A long position profits when an asset's price rises, and a short position profits when its price falls."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell."],["short-squeeze","Short squeeze","A short squeeze is a rapid price rise that forces short sellers to buy back their positions, through stop-losses or liquidation, which pushes the price even higher."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"en","term":"Futures basis","aka":["basis","futures premium","contango and backwardation"],"short":"The futures basis is the difference between a futures contract's price and the spot price of the same asset, often expressed as an annualised percentage.","body":[["Basis = futures price − spot price. When futures trade above spot, the basis is positive, a state called contango. When they trade below, it is negative, called backwardation. In crypto, ",["dated futures","delivery-futures"]," have usually traded at a premium, reflecting demand for leveraged long exposure and the cost of capital."],["To compare contracts with different expiry dates, traders annualise the basis: divide the percentage premium by the days to expiry and multiply by 365. A 2% premium on a 30-day ",["contract","smart-contract"]," is far higher annualised than 2% on a 180-day one."],["The basis shrinks toward zero as a delivery contract approaches expiry, because it settles at the ",["index price","index-price"],". That is the idea behind the ",["cash-and-carry","funding-rate-arbitrage"]," or basis trade: buy spot, sell the future, and earn the premium. ",["Perpetual futures","perpetual-futures"]," have no expiry, so their premium is handled by the ",["funding rate","funding-rate"]," instead. A very high basis also signals heavy leveraged demand."]],"example":"Suppose BTC spot is 60,000 USDT and the contract expiring in 60 days trades at 60,900. The basis is 900 USDT, or 1.5% of spot. Annualised, that is 1.5% × 365 ÷ 60 ≈ 9.1% a year. A trader who buys 1 BTC spot and sells 1 BTC of that future locks in roughly 900 USDT at expiry, minus fees, whatever happens to the price.","mistakes":["Comparing raw basis between contracts with different expiries instead of annualising it.","Calling a basis trade risk-free while ignoring exchange risk and margin needs on the short future.","Confusing the basis of dated futures with the funding rate of perpetuals."],"faq":[{"q":"What is contango in crypto futures?","a":"Contango means futures trade above spot, a positive basis. It is the usual state in crypto when demand for leveraged longs is healthy."},{"q":"What does a negative basis mean?","a":"Futures trade below spot, called backwardation. It often appears in fearful markets or when demand to short is strong."}],"title":"What is futures basis in crypto? Contango explained","description":"Learn what futures basis is, how to annualise it, what contango and backwardation mean and how basis trades work.","related":[["delivery-futures","Delivery (quarterly) futures","Delivery futures are crypto futures contracts with a fixed expiry date, such as a weekly or quarterly contract, that settle at a set price when they expire."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["index-price","Index price","The index price is a reference price for an asset calculated from a weighted average of spot prices on several major exchanges, used to anchor futures pricing."],["funding-rate-arbitrage","Funding rate arbitrage","Funding rate arbitrage is a market-neutral strategy that collects funding payments by holding opposite positions, usually spot long and perpetual short, so price moves largely cancel out."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"en","term":"Deposit network (chain selection)","aka":["withdrawal network","transfer network","chain selection"],"short":"A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one.","body":[["Many assets exist on several blockchains. ",["USDT","usdt"],", for example, is issued on Tron (TRC-20), ",["Ethereum","ethereum"]," (ERC-20), BNB Smart Chain, Solana, TON and others. These are separate ledgers. A token sent over one network does not appear on another by itself."],["When you withdraw, the exchange asks you to pick a network and shows the fee and minimum amount for each. When you deposit, the exchange shows an address for the network you select. Fees, speed and the number of ",["confirmations","block-confirmations"]," required differ by network and by exchange."],"If you send over a network that the receiver does not support, the funds may still exist on-chain but not be credited. Some exchanges can recover them for a fee, others cannot. Always match the network on both sides before sending."],"example":["Suppose you move 500 USDT from Exchange A to Exchange B. Exchange B lists deposits on TRC-20 and ERC-20. Exchange A shows a ",["withdrawal fee","withdrawal-fee"]," of 1 USDT on TRC-20 and 4 USDT on ERC-20, as illustrative figures. You choose TRC-20 on both sides, paste the address starting with T, and receive 499 USDT. Had you chosen BNB Smart Chain on Exchange A, the tokens could have been sent to a network Exchange B does not credit."],"mistakes":["Assuming that because both addresses start with 0x, any EVM network will work.","Picking the cheapest network without checking that the receiving side supports it.","Ignoring the minimum deposit amount, which can leave a small transfer uncredited."],"faq":[{"q":"What happens if I choose the wrong network?","a":"The transfer usually completes on-chain but the receiver does not see it. Contact the receiving platform's support with the transaction hash; recovery is not guaranteed."},{"q":"Is TRC-20 the same as ERC-20?","a":"No. TRC-20 is a token standard on Tron and ERC-20 is a token standard on Ethereum. They are different blockchains with different fees and addresses."}],"title":"What is a deposit network? Choosing the right chain","description":"Why exchanges ask you to pick a network, how TRC-20, ERC-20 and others differ, and what happens if you pick the wrong one.","related":[["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["memo-tag","Memo / destination tag","A memo or destination tag is an extra code attached to a transfer that tells an exchange which customer account should receive a deposit sent to a shared address."],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee."],["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"en","term":"Mempool","aka":["memory pool","pending transactions"],"short":"The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block.","body":[["When you send a transaction, it is broadcast to nodes, which check it and store it in their mempool. Each ",["node","node"]," keeps its own version, so there is no single global mempool, but they are usually similar. Miners or validators then pick transactions from the pool to build the next block."],["Block space is limited, so transactions usually compete on fees. On ",["Bitcoin","bitcoin"],", miners tend to prioritize transactions with a higher fee per virtual byte. On ",["Ethereum","ethereum"],", users set a priority tip on top of the base fee. When the mempool is crowded, low-fee transactions can wait for hours, and some may eventually drop out of nodes' pools."],["The mempool is also where ",["MEV","mev"]," happens on chains with a public mempool: bots watch pending trades and try to front-run or sandwich them. Some wallets offer private transaction routes to avoid this. If your transaction is stuck, options include waiting, using replace-by-fee or a speed-up feature to pay more, or cancelling with a replacement transaction where your wallet supports it."]],"example":"Suppose the Bitcoin mempool is busy and transactions paying 20 sat/vB are being confirmed, while yours paid 5 sat/vB. Your transaction is 140 vB, so you paid 700 satoshis. To bump it using replace-by-fee to 22 sat/vB, the new fee would be 140 x 22 = 3,080 satoshis, an extra 2,380 satoshis, and it would likely confirm within the next few blocks if demand stays the same.","mistakes":["Sending a transaction with the lowest possible fee during congestion and expecting it to confirm quickly.","Resending the same payment again while the first one is still pending, risking paying twice.","Placing large DEX swaps through the public mempool with wide slippage, which invites sandwich attacks."],"faq":[{"q":"Why is my transaction stuck in the mempool?","a":"Usually the fee is too low compared with other pending transactions. You can wait, or speed it up with a higher fee if your wallet supports replace-by-fee or a similar function."},{"q":"Can a transaction disappear from the mempool?","a":"Yes. Nodes can drop very low-fee transactions after a period or when the pool is full. The funds stay in your wallet if the transaction was never confirmed."}],"title":"What is the mempool? Pending crypto transactions explained","description":"What the mempool is, why crypto transactions get stuck pending, how fees decide priority and how to speed up a transaction.","related":[["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."],["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."],["mev","MEV (maximal extractable value)","MEV, or maximal extractable value, is the profit that block producers and specialised bots can make by choosing, inserting or reordering transactions inside a block, often at the expense of ordinary users."],["block-confirmations","Block confirmations","Block confirmations are the number of blocks added to a blockchain since the block that includes your transaction, and exchanges wait for a set number before crediting a deposit."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"It says sent, but it never arrived. Where do you look?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"en","term":"No-KYC exchange","aka":["non-KYC exchange","exchange without KYC","no ID exchange"],"short":"A no-KYC exchange is a platform that lets you trade crypto without verifying your identity, either fully or up to certain withdrawal limits.","body":[["There are a few types. Decentralized exchanges let you trade from your own wallet with no account at all. Some centralized exchanges allow unverified accounts with low withdrawal limits and limited features. ",["Instant swap","instant-convert"]," services and some ",["P2P","p2p-trading"]," marketplaces also operate with little or no identity check."],["People choose them for privacy, for speed, or because they lack documents. The trade-offs are real. Unregulated centralized platforms offer fewer protections if something goes wrong, can change their policy and suddenly request ",["KYC","kyc"]," before a withdrawal, and may restrict users from certain countries in their terms even if they do not check."],["If you use one, keep amounts within published limits, read the terms on ",["restricted regions","geo-restrictions"],", and withdraw to your own wallet rather than storing funds there. On DEXs, you control the keys, but you also carry the ",["smart contract","smart-contract"]," and scam risks yourself. Using a no-KYC service does not change your tax obligations, which depend on your country."]],"example":["Suppose a ",["centralized exchange","centralized-exchange"]," allows unverified accounts to withdraw up to the equivalent of 1 BTC per day. You deposit 1.5 BTC and trade it. When you try to withdraw everything, you can only move 1 BTC on day one and 0.5 BTC on day two. If the exchange's risk team flags your account in between, it can ask for KYC before releasing the remaining 0.5 BTC, which is a common clause in terms of service."],"mistakes":["Depositing more than the unverified withdrawal limit allows you to take out.","Ignoring terms that let the platform request identity documents before releasing funds.","Assuming no KYC means no tax reporting obligations."],"faq":[{"q":"Are no-KYC exchanges legal?","a":"It depends on where the platform and the user are. Many jurisdictions require exchanges to run KYC, while decentralized protocols are treated differently. Check the rules in your country."},{"q":"Can a no-KYC exchange ask for ID later?","a":"Yes. Many terms allow the exchange to request verification at any time, for example when a withdrawal is large or flagged by monitoring."}],"title":"What is a no-KYC exchange? Risks and limits","description":"What a no-KYC exchange is, how DEXs and unverified accounts work, what limits apply and the trade-offs of skipping identity checks.","related":[["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"How does KYC work, and who should get your ID?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"en","term":"Fiat on-ramp","aka":["on-ramp","fiat gateway","buy crypto with card"],"short":"A fiat on-ramp is any service that turns government money like dollars or euros into crypto, such as a bank transfer to an exchange, a card purchase or a P2P trade.","body":[["Common on-ramps include bank deposits to a ",["centralized exchange","centralized-exchange"],", buying with a debit or credit card, ",["P2P","p2p-trading"]," marketplaces where you pay another user directly, and third-party payment providers built into wallets. The reverse direction, crypto back to fiat, is called an off-ramp."],"Each route has different costs and speed. Bank transfers are often cheap but can take time. Cards are instant but usually carry higher fees, and some banks block crypto purchases. P2P can offer local payment methods but needs care with counterparties. Payment providers inside wallets are convenient but often add a spread on top of the shown fee.",["Almost every regulated on-ramp requires ",["KYC","kyc"],". Before choosing one, compare the full cost: the deposit fee, the trading fee and the exchange rate used. Many people buy a ",["stablecoin","stablecoin"]," such as ",["USDT","usdt"]," or ",["USDC","usdc"]," first and then trade that for other coins. Available methods depend heavily on your country and bank."]],"example":"Suppose you want to turn 1,000 EUR into USDC. Route A is a bank transfer to an exchange with no deposit fee, then a market trade with a 0.1% fee, giving about 999 EUR worth of USDC. Route B is a card purchase with a 2% fee plus a 1% spread built into the rate, leaving about 970 EUR worth. Route A is 29 EUR cheaper but may take a day; route B is instant.","mistakes":["Comparing only the advertised fee and missing the spread hidden in the exchange rate.","Using a card cash advance option by accident and paying extra bank charges.","Paying a P2P seller outside the platform's escrow process."],"faq":[{"q":"What is the cheapest way to buy crypto with fiat?","a":"Bank transfers to an exchange are often cheaper than cards, but it depends on your bank, country and exchange. Compare the final amount you receive, not just the listed fee."},{"q":"What is the difference between an on-ramp and an off-ramp?","a":"An on-ramp converts fiat money into crypto. An off-ramp converts crypto back into fiat, usually to your bank account."}],"title":"What is a fiat on-ramp? Ways to buy crypto with cash","description":"What a fiat on-ramp is, how bank transfers, cards and P2P compare, and how to see the real cost of turning cash into crypto.","related":[["p2p-trading","P2P (C2C) trading","P2P (C2C) trading is buying or selling crypto directly with another user, paying in local money through bank transfer or payment apps while the platform holds the crypto in escrow."],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"First deposit: where does the money come from, and where does it go?"},"coin":null,"tool":null,"cta":true}});
